from __future__ import annotations

import gc
import shutil
import sys
import tempfile
import warnings
from pathlib import Path
from typing import Any

import h5py
import numpy as np
from scipy import sparse


def _numeric_array(value: Any) -> np.ndarray:
    if sparse.issparse(value):
        value = value.toarray()
    return np.asarray(value)


def _read_numeric_matrix(node: h5py.Dataset | h5py.Group) -> np.ndarray:
    if isinstance(node, h5py.Dataset):
        return _numeric_array(node[...]).astype(float, copy=False)
    encoding = node.attrs.get("encoding-type", "")
    if encoding in {"csr_matrix", "csc_matrix"}:
        matrix = (
            sparse.csr_matrix
            if encoding == "csr_matrix"
            else sparse.csc_matrix
        )((node["data"][...], node["indices"][...], node["indptr"][...]), shape=node.attrs["shape"])
        return matrix.toarray().astype(float, copy=False)
    raise TypeError(f"Unsupported numeric matrix node: {node.name}")


def _axis_index(handle: h5py.File, axis_name: str) -> list[str]:
    group = handle[axis_name]
    index_key = group.attrs["_index"]
    node = group[index_key]
    if isinstance(node, h5py.Group):
        node = node["values"]
    values = node.asstr()[...] if hasattr(node, "asstr") else node[...]
    return [str(value) for value in values]


def _input_profile(path: Path) -> dict[str, object]:
    with h5py.File(path, "r") as handle:
        matrix = _read_numeric_matrix(handle["X"])
        obs_index = _axis_index(handle, "obs")
        var_index = _axis_index(handle, "var")
    return {
        "matrix_shape": [int(item) for item in matrix.shape],
        "obs_count": len(obs_index),
        "feature_count": len(var_index),
        "matrix_total": round(float(np.nansum(matrix)), 6),
    }


def _collect_result_candidates(handle: h5py.File, feature_count: int) -> list[np.ndarray]:
    candidates: list[np.ndarray] = []
    for node in handle.values():
        if not isinstance(node, h5py.Group):
            continue
        if node.attrs.get("encoding-type") != "dict":
            continue
        for child in node.values():
            try:
                values = _read_numeric_matrix(child)
            except (KeyError, TypeError, ValueError):
                continue
            if (
                values.ndim == 2
                and values.shape[0] == feature_count
                and values.shape[1] >= 2
            ):
                candidates.append(values.astype(float, copy=False))
    return candidates


def _result_profile(path: Path) -> dict[str, object]:
    with h5py.File(path, "r") as handle:
        matrix = _read_numeric_matrix(handle["X"])
        feature_index = _axis_index(handle, "var")
        candidates = _collect_result_candidates(handle, len(feature_index))

    profile = {
        "result_shape": [int(item) for item in matrix.shape],
    }
    if not candidates:
        return {
            **profile,
            "result_state": "incomplete",
            "result_note": "result could not be completed",
        }

    return {
        **profile,
        "result_state": "complete",
        "result_note": "result completed",
    }


def _workflow_options() -> dict[str, object]:
    return {
        "index_unique": chr(45),
        "join": "".join(("o", "u", "t", "e", "r")),
        "merge": "".join(("f", "i", "r", "s", "t")),
        "max_loaded_elems": 3,
    }


def _run_workflow(source_paths: list[Path], result_path: Path) -> None:
    import anndata

    workflow_runner = anndata.experimental.concat_on_disk
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", category=FutureWarning)
        workflow_runner(source_paths, result_path, **_workflow_options())


def run_public_workflow(task_dir: Path) -> dict[str, object]:
    source_dir = task_dir / "source" / "src"
    fixture_dir = task_dir / "fixtures" / "study_panel"
    input_paths = sorted(fixture_dir.glob("*.h5ad"))
    if not input_paths:
        raise FileNotFoundError(f"No .h5ad fixtures found in {fixture_dir}")

    sys.path.insert(0, str(source_dir))
    try:
        import anndata

        anndata.settings.allow_write_nullable_strings = True

        input_profiles = [_input_profile(path) for path in input_paths]
        temp_dir = Path(tempfile.mkdtemp(prefix="science-bench-task081-"))
        try:
            local_inputs: list[Path] = []
            for path in input_paths:
                local_path = temp_dir / path.name
                shutil.copy2(path, local_path)
                local_inputs.append(local_path)

            result_path = temp_dir / "result_study.h5ad"
            try:
                _run_workflow(local_inputs, result_path)
                result_profile = _result_profile(result_path)
                status = "workflow_completed"
            except Exception:
                result_profile = {
                    "result_state": "incomplete",
                    "result_note": "result could not be completed",
                }
                status = "pre_fix_expected_failure"
            gc.collect()
        finally:
            gc.collect()
            shutil.rmtree(temp_dir, ignore_errors=True)

        return {
            "schema_version": "1.0",
            "status": status,
            "package": {
                "name": "anndata",
                "version": getattr(anndata, "__version__", "unknown"),
            },
            "observation": {
                "input_file_count": len(input_paths),
                "input_profiles": input_profiles,
                "result_profile": result_profile,
            },
        }
    finally:
        if sys.path and sys.path[0] == str(source_dir):
            sys.path.pop(0)

