def _reindex_alt_element(reindexer, value, *, fill_value=None):
    """Align one element of an alt-axis mapping (e.g. ``varm`` for ``axis="obs"``).

    The elements handed in here come from :func:`read_as_backed`, so they may still
    live on disk (:class:`h5py.Dataset`, :class:`zarr.Array` or
    :class:`~anndata.abc.CSRDataset`/:class:`~anndata.abc.CSCDataset`).  The
    reindexing machinery in :mod:`anndata._core.merge` works on in-memory
    containers, so an element is pulled into memory exactly when the alignment
    changes it.  Elements that are already aligned are handed back untouched so
    they can be copied to the output store without being read in full.
    """
    if isinstance(value, Mapping):
        # Nested mappings are aligned element-wise, mirroring the leaves above.
        return {
            k: _reindex_alt_element(reindexer, v, fill_value=fill_value)
            for k, v in value.items()
        }
    old_idx = getattr(reindexer, "old_idx", None)
    if old_idx is None:  # e.g. `IdentityReindexer`: nothing to align against
        return value
    shape = getattr(value, "shape", ())
    if len(shape) == 0 or shape[0] != len(old_idx):
        # Not aligned to the alt axis, so there is nothing sensible to reindex.
        return value
    if reindexer.no_change:
        return value
    return reindexer(to_memory(value), axis=0, fill_value=fill_value)


class _ReindexedMapping(Mapping):
    """Lazily aligned view on an alt-axis mapping of a single input store.

    Values are aligned (and, if needed, read into memory) on access, so merging
    a mapping of many keys never needs all of them in memory at once.
    """

    def __init__(self, mapping: Mapping, reindexer, *, fill_value=None):
        self._mapping = mapping
        self._reindexer = reindexer
        self._fill_value = fill_value

    def __getitem__(self, key):
        return _reindex_alt_element(
            self._reindexer, self._mapping[key], fill_value=self._fill_value
        )

    def __iter__(self):
        return iter(self._mapping)

    def __len__(self) -> int:
        return len(self._mapping)


def _as_dict(mapping: Mapping) -> dict:
    """Materialize (possibly nested) mappings as plain dicts for writing."""
    return {
        k: _as_dict(v) if isinstance(v, Mapping) else v for k, v in mapping.items()
    }


